/**
 * next/image loader for the static (GitHub Pages) build.
 * Maps each requested width to a WebP variant pre-generated by
 * scripts/build-image-variants.mjs, so phones still get small files.
 */

export const VARIANT_WIDTHS = [320, 640, 960, 1280, 1600] as const;

const base = process.env.NEXT_PUBLIC_BASE_PATH ?? "";

export default function staticImageLoader({ src, width }: { src: string; width: number; quality?: number }) {
  const m = src.match(/^\/images\/([^/]+)\.(jpe?g|png)$/i);
  if (!m) return `${base}${src}`;
  const w = VARIANT_WIDTHS.find((v) => v >= width) ?? VARIANT_WIDTHS[VARIANT_WIDTHS.length - 1];
  return `${base}/images/_w/${m[1]}-${w}.webp`;
}
